globalCss:
/* Gothic 全局样式 */

:root {
  --gothic-purple: #2d1b4e;
  --gothic-blood: #8b1a1a;
  --gothic-black: #0a0a0a;
  --gothic-gold: #c9a227;
}

/* 金色发光 */
.gothic-glow {
  text-shadow:
    0 0 10px var(--gothic-gold),
    0 0 20px rgba(201, 162, 39, 0.3);
}

/* 尖拱装饰 */
.gothic-arch {
  clip-path: polygon(0 100%, 0 20%, 50% 0, 100% 20%, 100% 100%);
}

/* 装饰边框 */
.gothic-border {
  border: 2px solid rgba(201, 162, 39, 0.4);
  box-shadow: inset 0 0 20px rgba(10, 10, 10, 0.8);
}

/* 玫瑰窗装饰 */
.gothic-rose-window {
  background: radial-gradient(
    circle,
    var(--gothic-purple) 20%,
    var(--gothic-blood) 40%,
    var(--gothic-black) 60%
  );
}
@keyframes gothic-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes gothic-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.gothic-card {
  position: relative;
  overflow: hidden;
}

.gothic-card::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.3s ease;
  background: linear-gradient(135deg, rgba(45, 27, 78, 0.05), transparent);
  pointer-events: none;
}

.gothic-card:hover::before {
  opacity: 1;
}

.gothic-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(45, 27, 78, 0.08);
}

.gothic-animate-in {
  animation: gothic-fade-in 0.5s ease-out both;
}
